// Builds src/components/icon-data.ts: the only icons the site ships.
// Icons are inlined into the HTML at build time; nothing is fetched at runtime.
//
// To add an icon: put its Lucide name (https://lucide.dev/icons) in NAMES,
// run `npm run icons`, and commit the regenerated file.
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';

const NAMES = [
  // Used by the design system components
  'arrow-right', 'check', 'chevron-down', 'chevron-right', 'circle-alert', 'circle-check',
  'clipboard-check', 'factory', 'gauge', 'house', 'image-off', 'inbox', 'info',
  'loader-circle', 'mail', 'map-pin', 'menu', 'phone', 'ruler', 'smartphone', 'sprout',
  'triangle-alert', 'wrench', 'x',
  // Used by pages
  'badge-check', 'droplets', 'send', 'shield-check', 'sun', 'zap',
];

const requireFromHere = createRequire(import.meta.url);
const lucide = requireFromHere('@iconify-json/lucide/icons.json');

function lucideIcon(name) {
  const alias = lucide.aliases?.[name]?.parent;
  const icon = lucide.icons[name] ?? (alias && lucide.icons[alias]);
  if (!icon) throw new Error(`Lucide has no icon called "${name}"`);
  return { body: icon.body, size: icon.width ?? lucide.width ?? 24 };
}

// WhatsApp is a brand mark, not in Lucide. Local copy of Simple Icons (CC0) 13.0.0.
function whatsapp() {
  const svg = readFileSync(new URL('../src/assets/icons/whatsapp.svg', import.meta.url), 'utf8');
  const d = svg.match(/<path d="([^"]+)"/)?.[1];
  if (!d) throw new Error('Could not read the WhatsApp path');
  return { body: `<path fill="currentColor" d="${d}"/>`, size: 24 };
}

const icons = { whatsapp: whatsapp() };
for (const name of [...NAMES].sort()) icons[name] = lucideIcon(name);

const out = `// Generated by scripts/icons.mjs from @iconify-json/lucide and src/assets/icons. Do not edit by hand.
export const ICONS = ${JSON.stringify(icons, null, 2)} as const satisfies Record<string, { body: string; size: number }>;

export type IconName = keyof typeof ICONS;
`;
writeFileSync(new URL('../src/components/icon-data.ts', import.meta.url), out);
console.log(`Wrote ${Object.keys(icons).length} icons to src/components/icon-data.ts`);
